class FinanceStatementPaperLayoutTest {
 @Test void physicalSourcePrintPreservesOriginalScaleMarginsAndHeaderWrapWithoutInventedTitles()throws Exception{
  var meta=metadata();var wrapper=FinanceStatementPaperLayout.metadata("subcontractStatement",meta);var raw=(Map<?,?>)wrapper.get("paperLayout");assertThat(raw.get("version")).isEqualTo(2);var source=(Map<?,?>)raw.get("sourcePrint");assertThat(source.get("fitToPage")).isEqualTo(false);assertThat(source.get("scalePercent")).isEqualTo(100);assertThat((List<?>)source.get("repeatRows")).isEmpty();assertThat((List<?>)source.get("columnWidthsPoints")).hasSize(19);
  var cols=columns("subcontractStatement");var layout=FinanceTemplateLayouts.create("statements/subcontract",Map.of("dateTo","2026-09-30"),cols,List.of(),meta,"匿名组织");byte[] bytes=new XlsxExportService().build(new ExportPayload(cols,List.of(),0).withLayout(layout),null,null);
  try(var book=new XSSFWorkbook(new ByteArrayInputStream(bytes))){var sheet=book.getSheetAt(0);assertThat(sheet.getFitToPage()).isFalse();assertThat(sheet.getPrintSetup().getScale()).isEqualTo((short)100);assertThat(sheet.getPrintSetup().getLandscape()).isFalse();assertThat(sheet.getRepeatingRows()).isNull();assertThat(sheet.getRepeatingColumns()).isNull();assertThat(sheet.getMargin(PageMargin.LEFT)).isEqualTo(.75d);assertThat(sheet.getMargin(PageMargin.TOP)).isEqualTo(1d);var style=sheet.getRow(2).getCell(4).getCellStyle();assertThat(style.getWrapText()).isTrue();assertThat(style.getShrinkToFit()).isFalse();assertThat(book.getFontAt(style.getFontIndex()).getFontHeightInPoints()).isEqualTo((short)12);assertThat(book.getFontAt(0).getFontName()).isEqualTo("宋体");assertThat(book.getFontAt(0).getScheme()).isEqualTo(FontScheme.NONE);}
 }
 @SuppressWarnings("unchecked") @Test void legacyFrozenPaperDoesNotSilentlyBecomeTheNewSourceGeometry(){
  var meta=metadata();meta.put("paperLayout",Map.of("version","1","templateKey","supplierStatement"));var paper=FinanceStatementPaperLayout.layout("supplierStatement",meta);assertThat(paper.version()).isEqualTo(1);assertThat(paper.sourcePrint()).isEmpty();var wrapper=FinanceStatementPaperLayout.metadata("supplierStatement",meta);assertThat(((Map<?,?>)wrapper.get("paperLayout")).containsKey("sourcePrint")).isFalse();
  var fresh=metadata();var frozen=(Map<String,Object>)FinanceStatementPaperLayout.metadata("supplierStatement",fresh).get("paperLayout");var wrong=new LinkedHashMap<>(frozen);wrong.put("geometrySha256","0".repeat(64));fresh.put("paperLayout",wrong);assertThatThrownBy(()->FinanceStatementPaperLayout.layout("supplierStatement",fresh)).isInstanceOf(IllegalArgumentException.class);wrong.put("version",3);assertThatThrownBy(()->FinanceStatementPaperLayout.layout("supplierStatement",fresh)).isInstanceOf(IllegalArgumentException.class);
  var missing=metadata();missing.put("reviewId",UUID.randomUUID());assertThatThrownBy(()->FinanceStatementPaperLayout.layout("supplierStatement",missing)).isInstanceOf(IllegalArgumentException.class);
 }
 @Test void exactBodyTextAndIsoDateKeepTheirWholeRawValueAndGrowInsteadOfShrinking()throws Exception{
  var cols=columns("supplierStatement");String code="BODY-CODE-ORIGINAL-TAIL-1234567890",date="2026-09-08T12:34:56+08:00";var row=Map.<String,Object>of("k0",date,"k1",code);var layout=FinanceTemplateLayouts.create("statements/supplier",Map.of("dateTo","2026-09-30"),cols,List.of(row),metadata(),"匿名组织");byte[] bytes=new XlsxExportService().build(new ExportPayload(cols,List.of(row),1).withLayout(layout),null,null);
  try(var book=new XSSFWorkbook(new ByteArrayInputStream(bytes))){var record=book.getSheetAt(0).getRow(layout.headerRow()+1);assertThat(record.getCell(0).getStringCellValue()).isEqualTo(date);assertThat(record.getCell(1).getStringCellValue()).isEqualTo(code);assertThat(record.getCell(1).getCellStyle().getWrapText()).isTrue();assertThat(record.getCell(1).getCellStyle().getShrinkToFit()).isFalse();assertThat(record.getHeightInPoints()).isGreaterThan(layout.rowHeight());}
 }
 @Test void fourActualXlsxWritersUseTheSameNativeMeasuredSourceGeometry()throws Exception{
  java.nio.file.Path root=java.nio.file.Path.of("..");if(!java.nio.file.Files.isRegularFile(root.resolve("contracts/finance-paper-layout/v2.json")))root=java.nio.file.Path.of(".");
  var fixtures=new com.fasterxml.jackson.databind.ObjectMapper().readTree(root.resolve("contracts/finance-paper-layout/v2.json").toFile());
  for(var entry:Map.of("subcontractStatement","subcontract","supplierStatement","supplier","otherReceivableStatement","other-receivable","clientStatement","client").entrySet()){
   var fixture=fixtures.path(entry.getKey());var cols=columns(entry.getKey());var row=new LinkedHashMap<String,Object>();for(int column=0;column<cols.size();column++)row.put("k"+column,fixture.path("rows").path(0).path(column).asText());
   var meta=metadata();var raw=fixture.path("layout");meta.put("canvasColumns",raw.path("canvasColumns").asInt());meta.put("supplementalWidths",new com.fasterxml.jackson.databind.ObjectMapper().convertValue(raw.path("widths"),java.util.List.class));meta.put("hiddenColumns",new com.fasterxml.jackson.databind.ObjectMapper().convertValue(raw.path("hiddenColumns"),java.util.List.class));
   var layout=FinanceTemplateLayouts.create("statements/"+entry.getValue(),Map.of("dateTo","2026-09-30"),cols,List.of(row),meta,"匿名组织");byte[] bytes=new XlsxExportService().build(new ExportPayload(cols,List.of(row),1).withLayout(layout),null,null);
   try(var book=new XSSFWorkbook(new ByteArrayInputStream(bytes))){assertThat(book.getSheetAt(0).getFitToPage()).isFalse();assertThat(book.getSheetAt(0).getPrintSetup().getScale()).isEqualTo((short)100);assertThat(book.getSheetAt(0).getColumnWidth(0)/256d).isCloseTo(layout.widths().getFirst(),within(1d/256));}
   if("true".equals(System.getenv("FINANCE_CAPTURE_PAPER"))){var output=root.resolve("tmp/finance-paper-native-oracle/actual-"+entry.getKey()+".xlsx");java.nio.file.Files.createDirectories(output.getParent());java.nio.file.Files.write(output,bytes);}
  }
 }
 @SuppressWarnings("unchecked") @Test void actualSnapshotCodecKeepsDecimalGeometryTextAndIntegerIdentityForTheWorker()throws Exception{
  java.nio.file.Path root=java.nio.file.Path.of("..");if(!java.nio.file.Files.isRegularFile(root.resolve("contracts/finance-paper-layout/v2.json")))root=java.nio.file.Path.of(".");
  var mapper=com.uten.imp.config.Jackson2ObjectMapperAutoConfiguration.domainObjectMapper();var fixtures=mapper.readValue(root.resolve("contracts/finance-paper-layout/v2.json").toFile(),new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});
  var codec=org.mockito.Mockito.mock(com.uten.imp.features.finance.statement.FinanceStatementDocumentService.class,org.mockito.Mockito.CALLS_REAL_METHODS);org.springframework.test.util.ReflectionTestUtils.setField(codec,"json",mapper);var result=new LinkedHashMap<String,Object>();
  for(var entry:fixtures.entrySet()){
   var fixture=(Map<String,Object>)entry.getValue();var geometry=(Map<String,Object>)fixture.get("layout");var meta=metadata();meta.put("organizationName","匿名组织");var exactAmount=new java.math.BigDecimal("100.123456789012345678901234");meta.put("periodAmount",exactAmount);meta.put("paperTotals",Map.of("amount",List.of(Map.of("unit","CNY","value",exactAmount)),"qty",List.of(Map.of("unit","PCS","value",new java.math.BigDecimal("2"))),"deductionAmount",List.of(Map.of("unit","CNY","value",java.math.BigDecimal.ZERO))));meta.put("canvasColumns",geometry.get("canvasColumns"));meta.put("supplementalWidths",geometry.get("widths"));meta.put("hiddenColumns",geometry.get("hiddenColumns"));meta.putAll(FinanceStatementPaperLayout.metadata(entry.getKey(),meta));
   var previewPaper=(Map<String,Object>)meta.get("paperLayout");var previewSource=(Map<String,Object>)previewPaper.get("sourcePrint");((Map<String,Object>)previewSource.get("marginsPoints")).put("left",54.0d);
   var rows=new ArrayList<Map<String,Object>>();for(Object raw:(List<?>)fixture.get("rows")){var line=new LinkedHashMap<String,Object>();var values=(List<?>)raw;for(int column=0;column<values.size();column++){line.put("k"+column,values.get(column));}rows.add(line);}
   var preview=new LinkedHashMap<String,Object>();preview.put("columns",columns(entry.getKey()));preview.put("rows",rows);preview.put("documentMetadata",meta);
   Object sealed=org.springframework.test.util.ReflectionTestUtils.invokeMethod(codec,"sealSnapshot",preview);String encoded=org.springframework.test.util.ReflectionTestUtils.invokeMethod(codec,"encode",sealed);
   var frozen=mapper.readValue(encoded,new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});var frozenMeta=(Map<String,Object>)frozen.get("documentMetadata");var layout=(Map<String,Object>)frozenMeta.get("paperLayout");var frozenSource=(Map<String,Object>)layout.get("sourcePrint");assertThat(layout.get("version")).isInstanceOf(Integer.class).isEqualTo(2);assertThat(layout.get("headerRow")).isInstanceOf(Integer.class);assertThat(((List<?>)layout.get("widths")).getFirst()).isInstanceOf(String.class);assertThat(((List<?>)frozenSource.get("columnWidthsPoints")).getFirst()).isInstanceOf(String.class);assertThat(((Map<?,?>)frozenSource.get("marginsPoints")).get("left")).isEqualTo("54.0");assertThat(mapper.writeValueAsString(frozen.get("rows"))).isEqualTo(mapper.writeValueAsString(rows));assertThat(frozenMeta.get("periodAmount")).isEqualTo(exactAmount.toPlainString());
   var getMeta=new LinkedHashMap<>(frozenMeta);getMeta.put("reviewId",UUID.randomUUID());getMeta.put("preparedBy","匿名实际制表人");getMeta.put("issuedDate","2026-10-01");var restored=(Map<String,Object>)FinanceStatementPaperLayout.metadata(entry.getKey(),getMeta).get("paperLayout");assertThat(restored.get("widths")).isEqualTo(layout.get("widths"));assertThat(restored.get("sourcePrint")).isEqualTo(frozenSource);assertThat(restored.get("geometrySha256")).isEqualTo(layout.get("geometrySha256"));assertThat(mapper.writeValueAsString(frozen)).isEqualTo(encoded);
   var oldFooter=(Map<String,Object>)layout.get("footer");var newFooter=(Map<String,Object>)restored.get("footer");var oldCells=(List<Map<String,Object>>)oldFooter.get("cells");var newCells=(List<Map<String,Object>>)newFooter.get("cells");for(int index=0;index<oldCells.size();index++)if(Set.of("money","qty","number").contains(oldCells.get(index).get("type")))assertThat(newCells.get(index).get("value")).isEqualTo(oldCells.get(index).get("value"));
   var workerRows=new ArrayList<List<String>>();for(Object raw:(List<?>)frozen.get("rows")){var line=(Map<String,Object>)raw;var values=new ArrayList<String>();for(int column=0;column<columns(entry.getKey()).size();column++){values.add(Objects.toString(line.get("k"+column),""));}workerRows.add(values);}result.put(entry.getKey(),Map.of("layout",restored,"headers",fixture.get("headers"),"rows",workerRows,"notice","匿名生产冻结序列化回放，非公司账务"));
   var forgedMeta=mapper.readValue(mapper.writeValueAsString(getMeta),new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});var forgedLayout=(Map<String,Object>)forgedMeta.get("paperLayout");var forgedSource=(Map<String,Object>)forgedLayout.get("sourcePrint");((List<Object>)forgedSource.get("columnWidthsPoints")).set(0,"55.0");assertThatThrownBy(()->FinanceStatementPaperLayout.layout(entry.getKey(),forgedMeta)).isInstanceOf(IllegalArgumentException.class);
  }
  if("true".equals(System.getenv("FINANCE_CAPTURE_PAPER"))){var output=root.resolve("tmp/finance-paper-native-oracle/v2-frozen-worker-fixtures.json");java.nio.file.Files.createDirectories(output.getParent());mapper.writerWithDefaultPrettyPrinter().writeValue(output.toFile(),result);}
 }
 @Test void frozenDecimalTextGeometryRetainsSupplementalWidthsAndHiddenColumns(){
  var meta=metadata();meta.put("paperLayout",Map.of("version",1,"templateKey","otherReceivableStatement"));meta.put("canvasColumns","17");meta.put("supplementalWidths",List.of("62.5","9.25","10","11","12","13","14"));meta.put("hiddenColumns",List.of("11","12","13","14","15","16"));
  var paper=FinanceStatementPaperLayout.layout("otherReceivableStatement",meta);
  assertThat(paper.canvasColumns()).isEqualTo(17);assertThat(paper.widths().subList(10,17)).containsExactly(62.5,9.25,10d,11d,12d,13d,14d);assertThat(paper.hiddenColumns()).containsExactly(11,12,13,14,15,16);
  meta.put("hiddenColumns",List.of("11.5"));assertThatThrownBy(()->FinanceStatementPaperLayout.layout("otherReceivableStatement",meta)).isInstanceOf(IllegalArgumentException.class);
 }
 @Test void fourSourceHeaderAnchorsAndPortraitAreIndependentOfExtraHeaderLines(){
  var metadata=metadata();for(var entry:Map.of("subcontractStatement",3,"supplierStatement",5,"otherReceivableStatement",2,"clientStatement",3).entrySet()){
   var paper=FinanceStatementPaperLayout.layout(entry.getKey(),metadata);assertThat(paper.headerRow()).as(entry.getKey()).isEqualTo(entry.getValue());assertThat(paper.landscape()).isFalse();var wrapper=FinanceStatementPaperLayout.metadata(entry.getKey(),metadata);assertThat(wrapper.get("paperLayout")).isInstanceOf(Map.class);
  }
  var source=FinanceStatementPaperLayout.layout("supplierStatement",metadata);assertThat(source.merges()).contains(new ExportTableLayout.Merge(1,1,1,6),new ExportTableLayout.Merge(4,4,0,6));assertThat(source.merges()).doesNotContain(new ExportTableLayout.Merge(1,1,1,7));
 }
 @Test void shortMaterialStatementKeepsA1A2A3AndExactFooterCellsAtOriginalRows()throws Exception{
  var cols=columns("otherReceivableStatement");var meta=metadata();var layout=FinanceTemplateLayouts.create("statements/other-receivable",Map.of("dateTo","2026-09-30"),cols,List.of(Map.of("k0","2026-09-01","k9","1.234567890123456789")),meta,"匿名组织");
  byte[] bytes=new XlsxExportService().build(new ExportPayload(cols,List.of(Map.of("k0","2026-09-01","k9","1.234567890123456789")),1).withLayout(layout),null,null);
  try(var book=new XSSFWorkbook(new ByteArrayInputStream(bytes))){var sheet=book.getSheetAt(0);assertThat(sheet.getRow(0).getCell(0).getStringCellValue()).contains("匿名组织");assertThat(sheet.getRow(1).getCell(0).getStringCellValue()).contains("匿名往来对象");assertThat(sheet.getRow(2).getCell(0).getStringCellValue()).isEqualTo("日期");assertThat(sheet.getRow(0).getHeightInPoints()).isEqualTo(55f);assertThat(sheet.getRow(1).getHeightInPoints()).isEqualTo(32f);
   assertThat(sheet.getRow(40).getCell(0).getStringCellValue()).isEqualTo("本月加工费总金额：");assertThat(new DataFormatter(Locale.ROOT).formatCellValue(sheet.getRow(40).getCell(3))).isEqualTo("1.234567890123456789");assertThat(sheet.getRow(40).getCell(5).getStringCellValue()).isEqualTo("人民币大写总金额：");assertThat(sheet.getRow(40).getCell(7).getStringCellValue()).isEqualTo("已算中文大写");assertThat(new DataFormatter(Locale.ROOT).formatCellValue(sheet.getRow(41).getCell(3))).isEqualTo("2.000000000000000001");assertThat(sheet.getRow(45).getCell(0).getStringCellValue()).isEqualTo("备注：匿名实际打印说明");assertThat(sheet.getRow(47).getCell(0).getStringCellValue()).contains("客户确认:");assertThat(sheet.getPrintSetup().getLandscape()).isFalse();assertThat(sheet.getMergedRegions()).anySatisfy(range->assertThat(range.formatAsString()).isEqualTo("D42:E42"));}
 }
 @Test void streamingFooterIsWrittenOnceAfterAllRowsAndNeverMovesSourceHeaderOrCountsTemplateBlanksAsData()throws Exception{
  var cols=columns("otherReceivableStatement");var rows=new ArrayList<Map<String,Object>>();for(int i=0;i<520;i++){rows.add(Map.of("k0","原行"+i,"k9","0.0001"));}var layout=FinanceTemplateLayouts.create("statements/other-receivable",Map.of("dateTo","2026-09-30"),cols,rows,metadata(),"匿名组织");byte[] bytes;
  try(var writer=new XlsxExportService().openStream(null,null);var output=new ByteArrayOutputStream()){writer.accept(new ExportPayload(cols,rows.subList(0,250),520).withLayout(layout));writer.accept(new ExportPayload(cols,rows.subList(250,520),520).withLayout(layout));assertThat(writer.rowCount()).isEqualTo(520);writer.finish(output);assertThat(writer.rowCount()).isEqualTo(520);bytes=output.toByteArray();}
  try(var book=new XSSFWorkbook(new ByteArrayInputStream(bytes))){var sheet=book.getSheetAt(0);assertThat(sheet.getRow(2).getCell(0).getStringCellValue()).isEqualTo("日期");assertThat(sheet.getRow(522).getCell(0).getStringCellValue()).isEqualTo("原行519");assertThat(sheet.getRow(523).getCell(0).getStringCellValue()).isEqualTo("本月加工费总金额：");assertThat(sheet.getRow(532).getCell(0).getStringCellValue()).contains("日");assertThat(book.getPrintArea(0)).contains("$J$");}
 }
 @Test void sideAndFooterAmountsStayUnavailableWhenSourceMissingAndMixedUnitsAreNeverAdded(){
  var meta=metadata();meta.put("paperTotals",Map.of("qty",List.of(Map.of("unit","PCS","value","1"),Map.of("unit","KG","value","2"))));var paper=FinanceStatementPaperLayout.layout("clientStatement",meta);assertThat(paper.footer().cells()).anySatisfy(cell->{assertThat(cell.rowOffset()).isZero();assertThat(cell.column()).isEqualTo(4);assertThat(cell.value()).isNull();assertThat(cell.pending()).isTrue();});var supplier=FinanceStatementPaperLayout.layout("supplierStatement",meta);assertThat(supplier.footer().cells()).anySatisfy(cell->{assertThat(cell.column()).isEqualTo(6);assertThat(cell.rowOffset()).isEqualTo(1);assertThat(cell.value()).isNull();assertThat(cell.pending()).isTrue();});
 }
 static List<ExportColumn> columns(String key){var out=new ArrayList<ExportColumn>();int size=FinanceTemplateContract.template(key).path("headers").size();for(int i=0;i<size;i++){out.add(new ExportColumn("k"+i,FinanceTemplateContract.header(key,i),i==size-1?"money":"text"));}return out;}
 static Map<String,Object> metadata(){var meta=new LinkedHashMap<String,Object>();meta.put("title","匿名组织\n2026年9月份对账单");meta.put("organizationName","匿名组织");meta.put("dateFrom","2026-09-01");meta.put("dateTo","2026-09-30");meta.put("headerLines",List.of(Map.of("key","customerName","label"," TO: ","value","匿名往来对象"),Map.of("key","phone","label","电话:","value","匿名号码"),Map.of("key","fax","label","传真:","value","匿名传真"),Map.of("key","address","label","地址：","value","匿名地址")));
  meta.put("footerLines",List.of(line("periodAmount","本月加工费总金额：","1.234567890123456789"),line("adjustedProcessingAmount","含税加工费金额","2.000000000000000001"),line("periodAmountUpper","人民币大写总金额：","已算中文大写"),line("closingBalance","截止2026年9月30日贵公司应付总金额：","3.0001"),line("closingMaterialWeight","总欠金本材料","4.000000001"),line("printRemark","备注：","匿名实际打印说明"),line("retention","已扣质保金：","匿名已核说明")));return meta;}
 static Map<String,Object> line(String key,String label,String value){return Map.of("key",key,"label",label,"value",value,"pending",false,"basis","匿名已算来源");}
}
